from typing import Dict, List

class NumberSorter:
    def __init__(self):
        self.num_dict: Dict[str, int] = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}

    def split_input(self, numbers: str) -> List[str]:
        return numbers.split()

    def sort_numbers(self, numbers: List[str]) -> str:
        if not numbers:
            return ""

        sorted_numbers = sorted(numbers, key=lambda x: self.num_dict[x])
        return ' '.join(sorted_numbers)

def sort_numbers(numbers: str) -> str:
    sorter = NumberSorter()
    return sorter.sort_numbers(numbers)

